SELECT DISTINCT * FROM (SELECT T.* FROM( SELECT ETR_ENTRUST_ADD.ASSET_TYPE1 as assetType1, #{effectFlag} effectFlag, bobrt.BID_MODLE bidModle, ETR_ENTRUST.ENTRUST_STATUS entrustStatus, decode(ETR_ENTRUST.ENTRUST_STATUS,'09',1,'02',2,'03',3,'04',4,'06',5,'05',6,'07',7) entrustStatusOrder, ETR_ENTRUST.ENTRUST_TYPE entrustType, ETR_ENTRUST.ENTRUST_ID entrustId, ETR_ENTRUST.INV_MANAGER_ID invManagerId, su1.real_name invManagerName, nvl(detail.PORTFOLIO_ID,PTL_PORTFOLIO.PORTFOLIO_ID) portfolioId, nvl(detail.PORTFOLIO_NAME,PTL_PORTFOLIO.PORTFOLIO_NAME) portfolioName, ETR_ENTRUST_ADD.ASSET_TYPE assetType, ETR_ENTRUST.FINPROD_TYPE2 finprodType2, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE ='F07' AND ETR_ENTRUST.PS IN ('03', '04','T56','T93','T94','T95','T96') THEN ETR_ENTRUST.STOCK_ID else(case when FIN_PRODUCT.FINPROD_MARKET_ID is not null then FIN_PRODUCT.FINPROD_MARKET_ID else ETR_ENTRUST_ADD.ASSET_TYPE_10 end) end finprodMarketId, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE ='F07' AND ETR_ENTRUST.PS IN('03','04') THEN ETR_ENTRUST.STOCK_ID ELSE FIN_PRODUCT.FINPROD_ID END finprodId, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE ='F07' AND ETR_ENTRUST.PS IN('03','04') AND ETR_ENTRUST.ENTRUST_TYPE NOT IN ('17', '18', '19', '20', '21') THEN ETR_ENTRUST.FINPROD_ID else (case when FIN_PRODUCT.FINPROD_MARKET_ID is not null then FIN_PRODUCT.FINPROD_ABBR else OPT_TARGET_INFO.TARGET_NAME end) end finprodAbbr, ETR_ENTRUST.PS Ps, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_07}, #{ASSET_TYPE_10}, #{ASSET_TYPE_12}) THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{BACK_LEND_DIRECTION} AND ITEM_CODE = ETR_ENTRUST_ADD.BUSI_PS) ELSE (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{PS} AND ITEM_CODE = ETR_ENTRUST.PS) END AS otherPs, ETR_ENTRUST_ADD.BUSI_PS busiPs, ETR_ENTRUST.TRADE_MARKET tradeMarket, decode( btm.OUTPUT_VALUE_1, 'EX004', '', decode( ETR_ENTRUST_ADD.ASSET_TYPE, 'F01', NVL(ETR_ENTRUST.ENTRUST_AMT, ETR_ENTRUST.ENTRUST_NUM), 'F10', NVL( ETR_ENTRUST.ENTRUST_NUM * 100, 0 ), NVL( ETR_ENTRUST.ENTRUST_AMT, ETR_ENTRUST.ENTRUST_NUM ) ) )entrustAmt, decode(ETR_ENTRUST_ADD.ASSET_TYPE,'F01',NVL(ETR_FINISH_STATUSA.FINISH_AMT * 100,0),'F10',NVL(ETR_FINISH_STATUSA.FINISH_AMT * 100,0),NVL(ETR_FINISH_STATUSA.FINISH_AMT,0)) finishAmt, NVL( ETR_ENTRUST.CCY , 'CNY' ) ccy, ETR_ENTRUST.ENTRUST_DATE entrustDate, ETR_ENTRUST.VDATE vdate, ETR_ENTRUST.MDATE mdate, /*B.TRADER trader, B.realName realName,*/ ETR_ENTRUST.REMARK remark, ETR_ENTRUST_ADD.BUSI_TYPE_POSITION busiTypePosition, ssai.sec_acct_name secAcctId, DECODE(ETR_ENTRUST_ADD.SETTLE_SPREED,0,'01',1,'02','2','03') settleSpeed, decode(ETR_ENTRUST_ADD.ASSET_TYPE,'F01','','F07',ETR_ENTRUST_ADD.TERM_DAYS,'F10',ETR_ENTRUST_ADD.TERM_DAYS,'F12',ETR_ENTRUST_ADD.TERM_DAYS,'F16',ETR_ENTRUST_ADD.TERM_DAYS,'') termDays, case WHEN ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' AND FIN_PRODUCT_ISSUE.ISSUE_CLASS = '01' THEN case when FIN_PRODUCT.COUPON_SPECIES = '01' AND FIN_PRODUCT_ISSUE.INT_TYPE = '02' THEN SDLDATA.ITEM_VALUE || '+' || to_char(FIN_PRODUCT_ISSUE.bp * 10000 ,'FM999,999,999,999,990.90') || ' BP' else to_char(FIN_PRODUCT_ISSUE.REFER_YIELD * 100 ,'FM999,999,999,999,990.9990') || ' %' END WHEN ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' AND FIN_PRODUCT_ISSUE.ISSUE_CLASS IN ('02','03') THEN CASE WHEN FIN_PRODUCT_ISSUE.TENDER_TARGET = '01' THEN bobp.BID_PRICE || ' %' WHEN FIN_PRODUCT_ISSUE.TENDER_TARGET = '02' THEN bobp.BID_PRICE || ' 元' WHEN FIN_PRODUCT_ISSUE.TENDER_TARGET = '03' THEN bobp.BID_PRICE || ' BP' ELSE bobp.BID_PRICE END when ETR_ENTRUST.PS in ('T68', 'T69') or ETR_ENTRUST_ADD.ASSET_TYPE = 'F07' then to_char(ETR_ENTRUST.PRICE*100, 'FM999,999,999,999,990.9990') when ETR_ENTRUST_ADD.BUSI_TYPE_POSITION='EX017' then to_char(decode(ETR_ENTRUST_ADD.PRICE_TYPE,#{PRICE_CLASS_01,jdbcType=VARCHAR},ROUND(ETR_ENTRUST.PRICE,4),#{PRICE_CLASS_02,jdbcType=VARCHAR},ROUND(ETR_ENTRUST_ADD.FULL_PRICE,4)), 'FM999,999,999,999,990.9990') when ETR_ENTRUST_ADD.BUSI_TYPE_POSITION='EX018' and ETR_ENTRUST.PRICE_MODEL = #{PRICE_MODEL_PRM03} then NULL WHEN ETR_ENTRUST_ADD.BUSI_TYPE_POSITION = 'EX0005' THEN NULL WHEN ETR_ENTRUST_ADD.BUSI_TYPE_POSITION = 'F02' AND ETR_ENTRUST.PRICE_MODEL = #{PRICE_MODEL_PRM03} THEN '0.00' when ETR_ENTRUST_ADD.BUSI_TYPE_POSITION='EX018' then to_char(ROUND(ETR_ENTRUST.price,3), 'FM999,999,999,999,990.990') else to_char(round(decode(btm.OUTPUT_VALUE_1,#{busiTypePosition02},decode(ETR_ENTRUST_ADD.CALCULATE_FIELD,'price',ETR_ENTRUST.PRICE,'exerYield',ETR_ENTRUST_ADD.EXER_YIELD*100,'matureYield',ETR_ENTRUST_ADD.MATURE_YIELD*100),#{busiTypePosition03},ETR_ENTRUST.PRICE,NVL(ETR_ENTRUST.PRICE, 0.00)),4), 'FM999,999,999,999,990.9990') end as etrPrice, CASE
WHEN ETR_ENTRUST_ADD.TARGET_TYPE = '01' THEN ROUND( decode(nvl( T5.ORDER_FINISH_AMT, 0 ),0,0, nvl( T5.ORDER_FINISH_AMT, 0 )/ nvl( ETR_ENTRUST.ENTRUST_NUM, 1 )), 4 )*100 ELSE ROUND( nvl( T5.ORDER_FINISH_AMT, 0 ) / nvl( ETR_ENTRUST.ENTRUST_AMT, 1 ), 4 )*100 END AS exeProgress, CASE
WHEN ETR_ENTRUST_ADD.TARGET_TYPE = '01' THEN ROUND( decode(nvl( T5.ENT_FINISH_AMT, 0 ),0,0, nvl( T5.ENT_FINISH_AMT, 0 )/ nvl( ETR_ENTRUST.ENTRUST_NUM, 1 )), 4 )*100 ELSE ROUND( nvl( T5.ENT_FINISH_AMT, 0 ) / nvl( ETR_ENTRUST.ENTRUST_AMT, 1 ), 4 ) *100 END AS dealProgress, CASE
WHEN etr_entrust_add.TARGET_TYPE = '01' THEN decode(ETR_ENTRUST_ADD.BUSI_TYPE_POSITION,'EX017',ROUND( nvl( T5.ORDER_FINISH_AMT/100, 0 ), 4 ),'EX018', ROUND( nvl( T5.ORDER_FINISH_AMT/100, 0 ), 4 ),ROUND( nvl( T5.ORDER_FINISH_AMT, 0 ), 4 )) ELSE ROUND( nvl( T5.ORDER_FINISH_AMT, 0 ), 4 ) END AS execFinishAmt, CASE
WHEN etr_entrust_add.TARGET_TYPE = '01' THEN decode(ETR_ENTRUST_ADD.BUSI_TYPE_POSITION,'EX017',ROUND( (nvl( etr_entrust.ENTRUST_NUM, 0 ) - nvl( T5.ORDER_FINISH_AMT, 0 ))/100, 4 ),'EX018',ROUND( (nvl( etr_entrust.ENTRUST_NUM, 0 ) - nvl( T5.ORDER_FINISH_AMT, 0 ))/100, 4 ),ROUND( nvl( etr_entrust.ENTRUST_NUM, 0 ) - nvl( T5.ORDER_FINISH_AMT, 0 ), 4 )) ELSE ROUND( nvl( etr_entrust.ENTRUST_AMT, 0 ) - nvl( T5.ORDER_FINISH_AMT, 0 ), 4 ) END AS execRemainderAmt, CASE
WHEN etr_entrust_add.TARGET_TYPE = '01' THEN decode(ETR_ENTRUST_ADD.BUSI_TYPE_POSITION,'EX017',ROUND( nvl( T5.ENT_FINISH_AMT/100, 0 ), 4 ),'EX018',ROUND( nvl( T5.ENT_FINISH_AMT/100, 0 ), 4 ),ROUND( nvl( T5.ENT_FINISH_AMT, 0 ), 4 )) ELSE ROUND( nvl( T5.ENT_FINISH_AMT, 0 ), 4 ) END AS transFinishAmt, CASE
WHEN etr_entrust_add.TARGET_TYPE = '01' THEN decode(ETR_ENTRUST_ADD.BUSI_TYPE_POSITION,'EX017',ROUND( (nvl( etr_entrust.ENTRUST_NUM, 0 ) - nvl( T5.ENT_FINISH_AMT, 0 ))/100, 4 ),'EX018',ROUND( (nvl( etr_entrust.ENTRUST_NUM, 0 ) - nvl( T5.ENT_FINISH_AMT, 0 ))/100, 4 ),ROUND( nvl( etr_entrust.ENTRUST_NUM, 0 ) - nvl( T5.ENT_FINISH_AMT, 0 ), 4 )) ELSE ROUND( nvl( etr_entrust.ENTRUST_AMT, 0 ) - nvl( T5.ENT_FINISH_AMT, 0 ), 4 ) END AS transRemainderAmt, to_char(ETR_ENTRUST_ADD.TRANSMIT_TIME,'hh24:mi:ss') transmitTime, to_char(ETR_ENTRUST_ADD.TRANSMIT_TIME,'hh24:mi') transmitTimeSer, ETR_ENTRUST.PRICE_MODEL priceModel, sci.ACCT_NAME trdAcctId, case when ETR_ENTRUST_ADD.BUSI_TYPE_POSITION='EX017' then ROUND(ETR_ENTRUST.ENTRUST_NUM/100,2) when ETR_ENTRUST_ADD.BUSI_TYPE_POSITION='EX018' then 0 when ETR_ENTRUST_ADD.BUSI_TYPE_POSITION in ('01', '34') then null else ETR_ENTRUST.ENTRUST_NUM end as entrustNum, ETR_ENTRUST_ADD.CALCULATE_FIELD calculateField, mcpdata.COUNTER_NAME counterId, ETR_ENTRUST_ADD.TARGET_TYPE, ETR_ENTRUST.TRADE_PLAT FROM (SELECT * FROM ETR_ENTRUST ORDER BY ENTRUST_DATE DESC) ETR_ENTRUST LEFT JOIN PTL_PORTFOLIO ON PTL_PORTFOLIO.PORTFOLIO_ID = ETR_ENTRUST.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = ETR_ENTRUST.FINPROD_ID LEFT JOIN ( SELECT EED.ENTRUST_ID, wm_concat ( FP.PORTFOLIO_ID ) AS PORTFOLIO_ID , wm_concat ( FP.PORTFOLIO_NAME ) AS PORTFOLIO_NAME FROM ETR_ENTRUST_DETAIL EED left join (select PORTFOLIO_ID,PORTFOLIO_NAME from PTL_PORTFOLIO order by PORTFOLIO_ID, PORTFOLIO_NAME) FP on EED.PORTFOLIO_ID = FP.PORTFOLIO_ID GROUP BY EED.ENTRUST_ID ) detail ON ETR_ENTRUST.ENTRUST_ID = detail.ENTRUST_ID
/* LEFT JOIN (SELECT listagg(TRADER, ',') within group ( order by TRADER ) TRADER, listagg(REAL_NAME, ',') within group(order by TRADER) realName, ENTRUST_ID as ENTRUST_ID FROM ETR_DISTRIBUTE LEFT JOIN SYS_USER ON ETR_DISTRIBUTE.TRADER = SYS_USER.USER_NAME GROUP BY ENTRUST_ID)B ON B.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID*/ LEFT JOIN (SELECT ENTRUST_ID,SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_FINISH_STATUS WHERE ENTRUST_ID != TRADE_ID GROUP BY ENTRUST_ID) ETR_FINISH_STATUSA ON ETR_FINISH_STATUSA.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN ETR_ENTRUST_ADD ON ETR_ENTRUST.ENTRUST_ID = ETR_ENTRUST_ADD.ENTRUST_ID LEFT JOIN OPT_TARGET_INFO ON ETR_ENTRUST_ADD.ASSET_TYPE_10 = OPT_TARGET_INFO.TARGET_ID
INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_PORTFOLIO.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID
/*LEFT JOIN (SELECT listagg(BID_PRICE, ',') within group (order by BID_PRICE) BID_PRICE, ENTRUST_ID as ENTRUST_ID FROM ETR_ENTRUST_BID_PRICE GROUP BY ENTRUST_ID) EEBP ON EEBP.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID*/ LEFT JOIN ETR_FINISH_STATUS T5 ON T5.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID AND ETR_ENTRUST.ENTRUST_ID = T5.TRADE_ID LEFT JOIN STL_SEC_ACCT_INFO ssai ON ETR_ENTRUST_ADD.SEC_ACCT_ID = ssai.SEC_ACCT_ID LEFT JOIN STL_CAPACCT_INFO sci ON sci.ACCT_NO = ssai.TRD_ACCT_ID LEFT JOIN SYS_USER su1 ON ETR_ENTRUST.INV_MANAGER_ID = su1.USER_NAME LEFT JOIN FIN_PRODUCT_TYPE_CONFIG btm ON (ETR_ENTRUST.FINPROD_TYPE2 = btm.INPUT_VALUE_2 OR btm.INPUT_VALUE_2 is null) AND (ETR_ENTRUST.Ps = btm.INPUT_VALUE_3 OR btm.INPUT_VALUE_3 is null) AND (ETR_ENTRUST.TRADE_PLAT = btm.INPUT_VALUE_1 OR btm.INPUT_VALUE_1 IS NULL) left join MST_COUNTER_PARTY mcpdata on ETR_ENTRUST.COUNTER_ID = mcpdata.COUNTER_ID LEFT JOIN FIN_PRODUCT_ISSUE ON FIN_PRODUCT_ISSUE.FINPROD_ID = ETR_ENTRUST.FINPROD_ID LEFT JOIN (select listagg(case when t3.TENDER_TARGET = '01' then to_char(t0.BID_PRICE * 100, 'FM999,999,999,999,990.9990') when t3.TENDER_TARGET = '02' then to_char(t0.BID_PRICE, 'FM999,999,999,999,990.9990') when t3.TENDER_TARGET = '03' then to_char(t0.BID_PRICE * 10000, 'FM999,999,999,999,990.90') end, ',') within group (order by t0.ENTRUST_ID) AS BID_PRICE, t0.ENTRUST_ID from ETR_ENTRUST_BID_PRICE t0 LEFT JOIN ETR_ENTRUST t1 on t1.ENTRUST_ID = t0.ENTRUST_ID LEFT JOIN FIN_PRODUCT t2 ON t2.FINPROD_ID = t1.FINPROD_ID LEFT JOIN FIN_PRODUCT_ISSUE t3 ON t3.FINPROD_ID = t2.FINPROD_ID group by t0.ENTRUST_ID) bobp ON bobp.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN (select * from SYS_DATADICT_LIST where DICT_CODE='SECRATE_DATA') SDLDATA on FIN_PRODUCT_ISSUE.INT_RATE_ID = SDLDATA.ITEM_CODE LEFT JOIN (select INPUT_VALUE_1 as Finprod_Type_Tg,INPUT_VALUE_2 as ps,INPUT_VALUE_3 as issueClass,OUTPUT_VALUE_1 as busi_type from FIN_PRODUCT_TYPE_CONFIG where CONFIG_TYPE='BUSI_TYPE_MAPPING') btm ON ETR_ENTRUST_ADD.ASSET_TYPE = btm.Finprod_Type_Tg AND ETR_ENTRUST.Ps = btm.ps AND ((ETR_ENTRUST.FINPROD_TYPE2 = 'F32' and btm.issueClass = FIN_PRODUCT_ISSUE.ISSUE_CLASS) or ETR_ENTRUST.FINPROD_TYPE2 != 'F32' and btm.issueClass is null) LEFT JOIN ( SELECT bo.BID_MODLE, brt.IS_WIN ,bo.FINPROD_ID ,bobp.ENTRUST_ID FROM BID_ORDER bo LEFT JOIN BID_ORDER_BID_PRICE bobp ON bobp.BID_ID = bo.BID_ID LEFT JOIN BID_RESULT_TOTAL brt ON brt.BID_ID = bo.BID_ID AND brt.STATUS = '01' AND brt.FINPROD_ID = bo.FINPROD_ID WHERE bo.IS_CANCEL = 'N' AND bo.TRADE_STATUS = '01' GROUP BY bo.BID_MODLE, brt.IS_WIN, bo.FINPROD_ID,bobp.ENTRUST_ID ) bobrt ON bobrt.FINPROD_ID = FIN_PRODUCT.FINPROD_ID AND bobrt.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID
AND ETR_ENTRUST.ENTRUST_STATUS IN(#{entrustAwait},#{entrustDistribute},#{entrustReceive},#{entrustUntread},#{entrustClose},#{entrustReturn},#{entrustRecall},#{entrustInwfl})
AND ETR_ENTRUST.ENTRUST_STATUS IN
#{item}
AND ETR_ENTRUST.PORTFOLIO_ID IN(
#{item}
)
AND ETR_ENTRUST.PS = #{ps}
AND ETR_ENTRUST_ADD.ASSET_TYPE = #{finprodType2}
AND ETR_ENTRUST_ADD.BUSI_TYPE_POSITION = #{busiTypePosition}
AND FIN_PRODUCT.FINPROD_MARKET_ID IN(
#{item}
)
AND ETR_ENTRUST.TRADE_MARKET = #{tradeMarket}
AND ETR_ENTRUST_ADD.SETTLE_SPREED = #{settleSpeed}
AND ETR_ENTRUST_ADD.SEC_ACCT_ID IN(
#{item}
)
AND ETR_ENTRUST.ENTRUST_ID LIKE concat(concat('%',#{entrustId,jdbcType=VARCHAR}),'%')
AND ETR_ENTRUST.INV_MANAGER_ID IN(
#{item}
)
AND to_char(ETR_ENTRUST.ENTRUST_DATE,'yyyy-MM-dd') >= #{entrustStartDate} AND to_char(ETR_ENTRUST.ENTRUST_DATE,'yyyy-MM-dd') <= #{entrustEndDate}
AND ETR_ENTRUST.CCY = #{ccy}
AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
AND sci.ACCT_NO = #{trdAcctId}
AND ssai.SEC_ACCT_NAME = #{trdAcctName} LIKE concat(concat('%',#{entrustId,jdbcType=VARCHAR}),'%')
union all SELECT WFL_ETR_ENTRUST_ADD.ASSET_TYPE1 as assetType1, #{effectFlag04} effectFlag, null as bidModle, WFL_ETR_ENTRUST.ENTRUST_STATUS entrustStatus, decode(WFL_ETR_ENTRUST.ENTRUST_STATUS,'09',1,'02',2,'03',3,'04',4,'06',5,'05',6,'07',7) entrustStatusOrder, WFL_ETR_ENTRUST.ENTRUST_TYPE entrustType, WFL_ETR_ENTRUST.ENTRUST_ID entrustId, WFL_ETR_ENTRUST.INV_MANAGER_ID invManagerId, su1.real_name invManagerName, nvl(detail.PORTFOLIO_ID,PTL_PORTFOLIO.PORTFOLIO_ID) portfolioId, nvl(detail.PORTFOLIO_NAME,PTL_PORTFOLIO.PORTFOLIO_NAME) portfolioName, WFL_ETR_ENTRUST_ADD.ASSET_TYPE assetType, WFL_ETR_ENTRUST.FINPROD_TYPE2 finprodType2, CASE WHEN WFL_ETR_ENTRUST_ADD.ASSET_TYPE ='F07' AND WFL_ETR_ENTRUST.PS IN ('03', '04','T56','T93','T94','T95','T96') THEN WFL_ETR_ENTRUST.STOCK_ID else(case when FIN_PRODUCT.FINPROD_MARKET_ID is not null then FIN_PRODUCT.FINPROD_MARKET_ID else WFL_ETR_ENTRUST_ADD.ASSET_TYPE_10 end) end finprodMarketId, CASE WHEN WFL_ETR_ENTRUST_ADD.ASSET_TYPE ='F07' AND WFL_ETR_ENTRUST.PS IN('03','04') THEN WFL_ETR_ENTRUST.STOCK_ID ELSE FIN_PRODUCT.FINPROD_ID END finprodId, CASE WHEN WFL_ETR_ENTRUST_ADD.ASSET_TYPE ='F07' AND WFL_ETR_ENTRUST.PS IN('03','04') AND WFL_ETR_ENTRUST.ENTRUST_TYPE NOT IN ('17', '18', '19', '20', '21') THEN WFL_ETR_ENTRUST.FINPROD_ID else (case when FIN_PRODUCT.FINPROD_MARKET_ID is not null then FIN_PRODUCT.FINPROD_ABBR else OPT_TARGET_INFO.TARGET_NAME end) end finprodAbbr, WFL_ETR_ENTRUST.PS Ps, CASE WHEN WFL_ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_07}, #{ASSET_TYPE_10}, #{ASSET_TYPE_12}) THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{BACK_LEND_DIRECTION} AND ITEM_CODE = WFL_ETR_ENTRUST_ADD.BUSI_PS) ELSE (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{PS} AND ITEM_CODE = WFL_ETR_ENTRUST.PS) END AS otherPs, WFL_ETR_ENTRUST_ADD.BUSI_PS busiPs, WFL_ETR_ENTRUST.TRADE_MARKET tradeMarket, decode( ETR_ENTRUST_ADD.BUSI_TYPE_POSITION, 'EX004', '', decode( WFL_ETR_ENTRUST_ADD.ASSET_TYPE, 'F01', NVL(WFL_ETR_ENTRUST.ENTRUST_AMT, WFL_ETR_ENTRUST.ENTRUST_NUM), 'F10', NVL( WFL_ETR_ENTRUST.ENTRUST_NUM * 100, 0 ), NVL( WFL_ETR_ENTRUST.ENTRUST_AMT, WFL_ETR_ENTRUST.ENTRUST_NUM ) ) )entrustAmt, /*decode(WFL_ETR_ENTRUST_ADD.ASSET_TYPE,'F01',NVL(ETR_FINISH_STATUSA.FINISH_AMT * 100,0),'F10',NVL(ETR_FINISH_STATUSA.FINISH_AMT * 100,0),NVL(ETR_FINISH_STATUSA.FINISH_AMT,0)) */ 0 finishAmt, NVL( WFL_ETR_ENTRUST.CCY , 'CNY' ) ccy, WFL_ETR_ENTRUST.ENTRUST_DATE entrustDate, WFL_ETR_ENTRUST.VDATE vdate, WFL_ETR_ENTRUST.MDATE mdate, /* B.TRADER trader, B.realName realName,*/ WFL_ETR_ENTRUST.REMARK remark, WFL_ETR_ENTRUST_ADD.BUSI_TYPE_POSITION busiTypePosition, ssai.sec_acct_name secAcctId, DECODE(WFL_ETR_ENTRUST_ADD.SETTLE_SPREED,0,'01',1,'02','2','03') settleSpeed, decode(WFL_ETR_ENTRUST_ADD.ASSET_TYPE,'F01','','F07',WFL_ETR_ENTRUST_ADD.TERM_DAYS,'F10',WFL_ETR_ENTRUST_ADD.TERM_DAYS,'F12',WFL_ETR_ENTRUST_ADD.TERM_DAYS,'F16',WFL_ETR_ENTRUST_ADD.TERM_DAYS,'') termDays, case WHEN WFL_ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' AND FIN_PRODUCT_ISSUE.ISSUE_CLASS = '01' THEN case when FIN_PRODUCT.COUPON_SPECIES = '01' AND FIN_PRODUCT_ISSUE.INT_TYPE = '02' THEN SDLDATA.ITEM_VALUE || '+' || to_char(FIN_PRODUCT_ISSUE.bp * 10000 ,'FM999,999,999,999,990.90') || ' BP' else to_char(FIN_PRODUCT_ISSUE.REFER_YIELD * 100 ,'FM999,999,999,999,990.9990') || ' %' END WHEN WFL_ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' AND FIN_PRODUCT_ISSUE.ISSUE_CLASS IN ('02','03') THEN CASE WHEN FIN_PRODUCT_ISSUE.TENDER_TARGET = '01' THEN bobp.BID_PRICE || ' %' WHEN FIN_PRODUCT_ISSUE.TENDER_TARGET = '02' THEN bobp.BID_PRICE || ' 元' WHEN FIN_PRODUCT_ISSUE.TENDER_TARGET = '03' THEN bobp.BID_PRICE || ' BP' ELSE bobp.BID_PRICE END when WFL_ETR_ENTRUST.PS in ('T68', 'T69') or WFL_ETR_ENTRUST_ADD.ASSET_TYPE = 'F07' then to_char(WFL_ETR_ENTRUST.PRICE*100,'FM999,999,999,999,990.9990') when WFL_ETR_ENTRUST_ADD.BUSI_TYPE_POSITION='EX017' then to_char(decode(WFL_ETR_ENTRUST_ADD.PRICE_TYPE,#{PRICE_CLASS_01,jdbcType=VARCHAR},ROUND(WFL_ETR_ENTRUST.PRICE,4),#{PRICE_CLASS_02,jdbcType=VARCHAR},ROUND(WFL_ETR_ENTRUST_ADD.FULL_PRICE,4)),'FM999,999,999,999,990.9990') when WFL_ETR_ENTRUST_ADD.BUSI_TYPE_POSITION='EX018' and WFL_ETR_ENTRUST.PRICE_MODEL = #{PRICE_MODEL_PRM03} then NULL WHEN WFL_ETR_ENTRUST_ADD.BUSI_TYPE_POSITION = 'EX0005' THEN NULL WHEN WFL_ETR_ENTRUST_ADD.BUSI_TYPE_POSITION = 'F02' AND WFL_ETR_ENTRUST.PRICE_MODEL = #{PRICE_MODEL_PRM03} THEN '0.00' when WFL_ETR_ENTRUST_ADD.BUSI_TYPE_POSITION='EX018' then to_char(ROUND(WFL_ETR_ENTRUST.price,3),'FM999,999,999,999,990.990') else to_char(round(decode(btm.OUTPUT_VALUE_1,#{busiTypePosition02},decode(WFL_ETR_ENTRUST_ADD.CALCULATE_FIELD,'price',WFL_ETR_ENTRUST.PRICE,'exerYield',WFL_ETR_ENTRUST_ADD.EXER_YIELD*100,'matureYield',WFL_ETR_ENTRUST_ADD.MATURE_YIELD*100),#{busiTypePosition03},WFL_ETR_ENTRUST.PRICE,NVL(WFL_ETR_ENTRUST.PRICE, 0.00)),4),'FM999,999,999,999,990.9990') end as etrPrice, /*CASE
WHEN WFL_ETR_ENTRUST_ADD.TARGET_TYPE = '01' THEN ROUND( decode(nvl( T5.ORDER_FINISH_AMT, 0 ), 0, 0, nvl( T5.ORDER_FINISH_AMT, 0 )/ nvl( WFL_ETR_ENTRUST.ENTRUST_NUM, 1 )), 4 )*100 ELSE ROUND( nvl( T5.ORDER_FINISH_AMT, 0 ) / nvl( WFL_ETR_ENTRUST.ENTRUST_AMT, 1 ), 4 )*100 END AS*/ 0 exeProgress, /*CASE
WHEN WFL_ETR_ENTRUST_ADD.TARGET_TYPE = '01' THEN ROUND( decode(nvl( T5.ENT_FINISH_AMT, 0 ), 0, 0, nvl( T5.ENT_FINISH_AMT, 0 )/ nvl( WFL_ETR_ENTRUST.ENTRUST_NUM, 1 )), 4 )*100 ELSE ROUND( nvl( T5.ENT_FINISH_AMT, 0 ) / nvl( WFL_ETR_ENTRUST.ENTRUST_AMT, 1 ), 4 )*100 END AS*/ 0 dealProgress, /*CASE
WHEN WFL_ETR_ENTRUST_ADD.TARGET_TYPE = '01' THEN ROUND( nvl( T5.ORDER_FINISH_AMT, 0 ), 4 ) ELSE ROUND( nvl( T5.ORDER_FINISH_AMT, 0 ), 4 ) END AS*/ 0 execFinishAmt, /*CASE
WHEN WFL_ETR_ENTRUST_ADD.TARGET_TYPE = '01' THEN ROUND( nvl( WFL_ETR_ENTRUST.ENTRUST_NUM, 0 ) - nvl( T5.ORDER_FINISH_AMT, 0 ), 4 ) ELSE ROUND( nvl( WFL_ETR_ENTRUST.ENTRUST_NUM, 0 ) - nvl( T5.ORDER_FINISH_AMT, 0 ), 4 ) END AS*/ 0 execRemainderAmt, /*CASE
WHEN WFL_ETR_ENTRUST_ADD.TARGET_TYPE = '01' THEN ROUND( nvl( T5.ENT_FINISH_AMT, 0 ), 4 ) ELSE ROUND( nvl( T5.ENT_FINISH_AMT, 0 ), 4 ) END AS*/ 0 transFinishAmt, /*CASE
WHEN WFL_ETR_ENTRUST_ADD.TARGET_TYPE = '01' THEN ROUND( nvl( WFL_ETR_ENTRUST.ENTRUST_NUM, 0 ) - nvl( T5.ENT_FINISH_AMT, 0 ), 4 ) ELSE ROUND( nvl( WFL_ETR_ENTRUST.ENTRUST_NUM, 0 ) - nvl( T5.ENT_FINISH_AMT, 0 ), 4 ) END AS*/ 0 transRemainderAmt, NULL transmitTime, NULL transmitTimeSer, WFL_ETR_ENTRUST.PRICE_MODEL priceModel, sci.ACCT_NAME trdAcctId, case when WFL_ETR_ENTRUST_ADD.BUSI_TYPE_POSITION='EX017' then ROUND(WFL_ETR_ENTRUST.ENTRUST_NUM/100,2) when WFL_ETR_ENTRUST_ADD.BUSI_TYPE_POSITION='EX018' then 0 when WFL_ETR_ENTRUST_ADD.BUSI_TYPE_POSITION in ('01', '34') then null else WFL_ETR_ENTRUST.ENTRUST_NUM end entrustNum, WFL_ETR_ENTRUST_ADD.CALCULATE_FIELD calculateField, mcpdata.COUNTER_NAME counterId, WFL_ETR_ENTRUST_ADD.TARGET_TYPE, WFL_ETR_ENTRUST.TRADE_PLAT FROM (SELECT * FROM WFL_ETR_ENTRUST ORDER BY ENTRUST_DATE DESC) WFL_ETR_ENTRUST LEFT JOIN PTL_PORTFOLIO ON PTL_PORTFOLIO.PORTFOLIO_ID = WFL_ETR_ENTRUST.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = WFL_ETR_ENTRUST.FINPROD_ID LEFT JOIN ( SELECT EED.ENTRUST_ID, wm_concat ( FP.PORTFOLIO_ID ) AS PORTFOLIO_ID , wm_concat ( FP.PORTFOLIO_NAME ) AS PORTFOLIO_NAME FROM ETR_ENTRUST_DETAIL EED left join (select PORTFOLIO_ID,PORTFOLIO_NAME from PTL_PORTFOLIO order by PORTFOLIO_ID, PORTFOLIO_NAME) FP on EED.PORTFOLIO_ID = FP.PORTFOLIO_ID GROUP BY EED.ENTRUST_ID ) detail ON WFL_ETR_ENTRUST.ENTRUST_ID = detail.ENTRUST_ID /*LEFT JOIN (SELECT listagg(TRADER, ',') within group ( order by TRADER ) TRADER, listagg(REAL_NAME, ',') within group(order by TRADER) realName, ENTRUST_ID as ENTRUST_ID FROM ETR_DISTRIBUTE LEFT JOIN SYS_USER ON ETR_DISTRIBUTE.TRADER = SYS_USER.USER_NAME GROUP BY ENTRUST_ID)B ON B.ENTRUST_ID = WFL_ETR_ENTRUST.ENTRUST_ID LEFT JOIN (SELECT ENTRUST_ID,SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_FINISH_STATUS WHERE ENTRUST_ID != TRADE_ID GROUP BY ENTRUST_ID) ETR_FINISH_STATUSA ON ETR_FINISH_STATUSA.ENTRUST_ID = WFL_ETR_ENTRUST.ENTRUST_ID*/ LEFT JOIN WFL_ETR_ENTRUST_ADD ON WFL_ETR_ENTRUST.ENTRUST_ID = WFL_ETR_ENTRUST_ADD.ENTRUST_ID LEFT JOIN OPT_TARGET_INFO ON WFL_ETR_ENTRUST_ADD.ASSET_TYPE_10 = OPT_TARGET_INFO.TARGET_ID LEFT JOIN FIN_PRODUCT_TYPE_CONFIG btm ON (WFL_ETR_ENTRUST.FINPROD_TYPE2 = btm.INPUT_VALUE_2 OR btm.INPUT_VALUE_2 is null) AND (WFL_ETR_ENTRUST.Ps = btm.INPUT_VALUE_3 OR btm.INPUT_VALUE_3 is null) AND (WFL_ETR_ENTRUST.TRADE_PLAT = btm.INPUT_VALUE_1 OR btm.INPUT_VALUE_1 IS NULL)
INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_PORTFOLIO.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID
/* LEFT JOIN (SELECT listagg(BID_PRICE, ',') within group (order by BID_PRICE) BID_PRICE, ENTRUST_ID as ENTRUST_ID FROM ETR_ENTRUST_BID_PRICE GROUP BY ENTRUST_ID) EEBP ON EEBP.ENTRUST_ID = WFL_ETR_ENTRUST.ENTRUST_ID LEFT JOIN ETR_FINISH_STATUS T5 ON T5.ENTRUST_ID = WFL_ETR_ENTRUST.ENTRUST_ID AND WFL_ETR_ENTRUST.ENTRUST_ID = T5.TRADE_ID*/ LEFT JOIN STL_SEC_ACCT_INFO ssai ON WFL_ETR_ENTRUST_ADD.SEC_ACCT_ID = ssai.SEC_ACCT_ID LEFT JOIN STL_CAPACCT_INFO sci ON sci.ACCT_NO = ssai.TRD_ACCT_ID LEFT JOIN SYS_USER su1 ON WFL_ETR_ENTRUST.INV_MANAGER_ID = su1.USER_NAME left join MST_COUNTER_PARTY mcpdata on WFL_ETR_ENTRUST.COUNTER_ID = mcpdata.COUNTER_ID left join ETR_ENTRUST_ADD on ETR_ENTRUST_ADD.ENTRUST_ID = WFL_ETR_ENTRUST.ENTRUST_ID LEFT JOIN FIN_PRODUCT_ISSUE ON FIN_PRODUCT_ISSUE.FINPROD_ID = WFL_ETR_ENTRUST.FINPROD_ID LEFT JOIN (select listagg(case when t3.TENDER_TARGET = '01' then to_char(t0.BID_PRICE * 100, 'FM999,999,999,999,990.9990') when t3.TENDER_TARGET = '02' then to_char(t0.BID_PRICE, 'FM999,999,999,999,990.9990') when t3.TENDER_TARGET = '03' then to_char(t0.BID_PRICE * 10000, 'FM999,999,999,999,990.90') end, ',') within group (order by t0.ENTRUST_ID) AS BID_PRICE, t0.ENTRUST_ID from WFL_ETR_ENTRUST_BID_PRICE t0 LEFT JOIN WFL_ETR_ENTRUST t1 on t1.ENTRUST_ID = t0.ENTRUST_ID LEFT JOIN FIN_PRODUCT t2 ON t2.FINPROD_ID = t1.FINPROD_ID LEFT JOIN FIN_PRODUCT_ISSUE t3 ON t3.FINPROD_ID = t2.FINPROD_ID group by t0.ENTRUST_ID) bobp ON bobp.ENTRUST_ID = WFL_ETR_ENTRUST.ENTRUST_ID LEFT JOIN (select * from SYS_DATADICT_LIST where DICT_CODE='SECRATE_DATA') SDLDATA on FIN_PRODUCT_ISSUE.INT_RATE_ID = SDLDATA.ITEM_CODE
AND WFL_ETR_ENTRUST.ENTRUST_STATUS IN(#{entrustInwfl})
AND WFL_ETR_ENTRUST.ENTRUST_STATUS IN
#{item}
AND WFL_ETR_ENTRUST.PORTFOLIO_ID IN(
#{item}
)
AND WFL_ETR_ENTRUST.PS =#{ps}
AND WFL_ETR_ENTRUST_ADD.ASSET_TYPE = #{finprodType2}
AND WFL_ETR_ENTRUST_ADD.BUSI_TYPE_POSITION = #{busiTypePosition}
AND FIN_PRODUCT.FINPROD_MARKET_ID IN(
#{item}
)
AND WFL_ETR_ENTRUST.TRADE_MARKET = #{tradeMarket}
AND WFL_ETR_ENTRUST_ADD.SETTLE_SPREED = #{settleSpeed}
AND WFL_ETR_ENTRUST_ADD.SEC_ACCT_ID IN(
#{item}
)
AND WFL_ETR_ENTRUST.ENTRUST_ID LIKE concat(concat('%',#{entrustId,jdbcType=VARCHAR}),'%')
AND WFL_ETR_ENTRUST.INV_MANAGER_ID IN(
#{item}
)
AND to_char(WFL_ETR_ENTRUST.ENTRUST_DATE,'yyyy-MM-dd') >= #{entrustStartDate} AND to_char(WFL_ETR_ENTRUST.ENTRUST_DATE,'yyyy-MM-dd') <= #{entrustEndDate}
AND WFL_ETR_ENTRUST.CCY = #{ccy}
AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
AND sci.ACCT_NO = #{trdAcctId}
) t left join SYS_DATADICT_LIST sdl on sdl.DICT_CODE='STATUS_VALID' and t.effectFlag=sdl.ITEM_CODE left join SYS_DATADICT_LIST sdl1 on sdl1.DICT_CODE='ENTRUST_STATUS' and t.entrustStatus=sdl1.ITEM_CODE left join SYS_DATADICT_LIST sdl2 on sdl2.DICT_CODE='PINAN_ASSET_TYPE' and t.finprodType2=sdl2.ITEM_CODE left join SYS_DATADICT_LIST sdl3 on sdl3.DICT_CODE='BUSI_TYPE_TG' and t.busiTypePosition=sdl3.ITEM_CODE left join SYS_DATADICT_LIST sdl4 on sdl4.DICT_CODE='PS' and t.PS=sdl4.ITEM_CODE left join SYS_DATADICT_LIST sdl5 on sdl5.DICT_CODE='TRADE_MARKET' and t.tradeMarket=sdl5.ITEM_CODE left join SYS_DATADICT_LIST sdl6 on sdl6.DICT_CODE='ACCOUNT_SPEED' and t.settleSpeed=sdl6.ITEM_CODE left join SYS_DATADICT_LIST sdl7 on sdl7.DICT_CODE='CCY' and t.ccy=sdl7.ITEM_CODE
order by t.finprodType2,t.entrustStatusOrder,t.busiTypePosition,t.ps)
order by ${sort} ${direction}

sql.where:
(sdl.ITEM_VALUE like '%' || #{search} || '%' OR sdl1.ITEM_VALUE like '%' || #{search} || '%' OR sdl2.ITEM_VALUE like '%' || #{search} || '%' OR sdl3.ITEM_VALUE like '%' || #{search} || '%' OR sdl4.ITEM_VALUE like '%' || #{search} || '%' OR sdl5.ITEM_VALUE like '%' || #{search} || '%' OR sdl6.ITEM_VALUE like '%' || #{search} || '%' OR sdl7.ITEM_VALUE like '%' || #{search} || '%' OR t.entrustId like '%' || #{search} || '%' OR t.invManagerId like '%' || #{search} || '%' OR t.invManagerName like '%' || #{search} || '%' OR t.portfolioId like '%' || #{search} || '%' OR t.portfolioName like '%' || #{search} || '%' OR t.finprodMarketId like '%' || #{search} || '%' OR t.finprodAbbr like '%' || #{search} || '%' OR t.remark like '%' || #{search} || '%' OR t.secAcctId like '%' || #{search} || '%' OR t.etrPrice like '%' || #{search} || '%'
OR round(t.entrustAmt,2)||'' = round(#{search},2) OR round(t.entrustNum,0)||'' = round(#{search},0) OR round(t.termDays,2)||'' = round(#{search},2) OR round(t.exeProgress,2)||'' = round(#{search},2) OR round(t.dealProgress,2)||'' = round(#{search},2)
OR TO_CHAR(t.entrustDate,'yyyy-MM-dd') ||''= #{search} OR TO_CHAR(t.entrustDate,'yyyy-MM-dd') ||''= #{year}||'-'||#{search} OR replace(TO_CHAR(t.entrustDate,'yyyy-MM-dd'),'-','/')=#{search} OR replace(TO_CHAR(t.entrustDate,'yyyy-MM-dd'),'-','/')=#{year}||'/'||#{search} OR t.transmitTimeSer = #{search} or t.transmitTime = #{search}
#{item}
)
AND t.tradeMarket in ('03','04','12') AND t.assetType in ('F01','F02','F07','F11','F37')

mapper.select:
SELECT decode(tpdp.is_cancel,'Y',#{TRADE_FLOW_STATUS03},#{TRADE_FLOW_STATUS02}) effectFlag,
FROM REG_FIN_PRODUCT_DEAL tpdp LEFT JOIN PTL_PORTFOLIO pp ON tpdp.portfolio_id = pp.portfolio_id LEFT JOIN FIN_PRODUCT fp ON tpdp.finprod_id = fp.finprod_id LEFT JOIN STL_SEC_ACCT_INFO ssai ON tpdp.sec_manage_acct_id = ssai.SEC_ACCT_ID LEFT JOIN MST_COUNTER_PARTY mcp ON tpdp.COUNTER_ID = mcp.counter_id LEFT JOIN MST_CFETS_CUSTOMER_TRADER mcct ON tpdp.COUNTER_TRADER= mcct.trader_id LEFT JOIN FIN_EXERCISE_PLAN T6 ON tpdp.FINPROD_ID = T6.FINPROD_ID AND T6.EXERCISE_TYPE ='02' WHERE tpdp.entrust_id = #{entrustId}
union all
SELECT #{TRADE_FLOW_STATUS01} effectFlag,
FROM WFL_REG_FIN_PRODUCT_DEAL tpdp LEFT JOIN PTL_PORTFOLIO pp ON tpdp.portfolio_id = pp.portfolio_id LEFT JOIN FIN_PRODUCT fp ON tpdp.finprod_id = fp.finprod_id LEFT JOIN STL_SEC_ACCT_INFO ssai ON tpdp.sec_manage_acct_id = ssai.SEC_ACCT_ID LEFT JOIN MST_COUNTER_PARTY mcp ON tpdp.COUNTER_ID = mcp.counter_id LEFT JOIN MST_CFETS_CUSTOMER_TRADER mcct ON tpdp.COUNTER_TRADER= mcct.trader_id LEFT JOIN FIN_EXERCISE_PLAN T6 ON tpdp.FINPROD_ID = T6.FINPROD_ID AND T6.EXERCISE_TYPE ='02' WHERE tpdp.entrust_id = #{entrustId}
union all
SELECT decode(tpdp.trade_status,'15',#{TRADE_FLOW_STATUS03},#{TRADE_FLOW_STATUS02}) as effectFlag,
FROM IBU_QUOTE_BOND tpdp LEFT JOIN IBU_QUOTE_BOND_DET tpdpa ON tpdp.QUOTE_ID = tpdpa.QUOTE_ID LEFT JOIN STL_SEC_ACCT_INFO ssai ON tpdp.SEC_MANAGE_ACCT_ID = ssai.SEC_ACCT_ID LEFT JOIN IBU_QUOTE_ETR_RE iqe ON iqe.QUOTE_ID = tpdp.QUOTE_ID LEFT JOIN PTL_PORTFOLIO pp ON iqe.portfolio_id = pp.portfolio_id LEFT JOIN FIN_PRODUCT fp ON tpdp.finprod_id = fp.finprod_id LEFT JOIN MST_CFETS_CUSTOMER_INFO mcp ON tpdpa.cp_party_id = mcp.party_id LEFT JOIN MST_CFETS_CUSTOMER_TRADER mcct ON tpdpa.CP_TRADER= mcct.trader_id LEFT JOIN FIN_EXERCISE_PLAN T6 ON tpdp.FINPROD_ID = T6.FINPROD_ID AND T6.EXERCISE_TYPE ='02' WHERE iqe.entrust_id = #{entrustId}
union all
SELECT #{TRADE_FLOW_STATUS01} effectFlag,
FROM WFL_IBU_QUOTE_BOND2 tpdp LEFT JOIN WFL_IBU_QUOTE_BOND_DET tpdpa ON tpdp.QUOTE_ID = tpdpa.QUOTE_ID LEFT JOIN WFL_IBU_QUOTE_ETR_RE wiqe ON wiqe.QUOTE_ID = tpdp.QUOTE_ID LEFT JOIN STL_SEC_ACCT_INFO ssai ON tpdp.SEC_MANAGE_ACCT_ID = ssai.SEC_ACCT_ID LEFT JOIN PTL_PORTFOLIO pp ON wiqe.portfolio_id = pp.portfolio_id LEFT JOIN FIN_PRODUCT fp ON tpdp.finprod_id = fp.finprod_id LEFT JOIN MST_CFETS_CUSTOMER_INFO mcp ON tpdpa.cp_party_id = mcp.party_id LEFT JOIN MST_CFETS_CUSTOMER_TRADER mcct ON tpdpa.CP_TRADER= mcct.trader_id LEFT JOIN FIN_EXERCISE_PLAN T6 ON tpdp.FINPROD_ID = T6.FINPROD_ID AND T6.EXERCISE_TYPE ='02' WHERE wiqe.entrust_id = #{entrustId} union all select decode(iqc.trade_status,'15',#{TRADE_FLOW_STATUS03},#{TRADE_FLOW_STATUS02}) as effectFlag,
from IBU_QUOTE_CREP iqc LEFT JOIN IBU_QUOTE_ETR_RE iqer ON iqer.QUOTE_ID = iqc.QUOTE_ID LEFT JOIN STL_SEC_ACCT_INFO ssai ON iqc.SEC_MANAGE_ACCT_ID = ssai.SEC_ACCT_ID LEFT JOIN PTL_PORTFOLIO pp ON iqer.portfolio_id = pp.portfolio_id LEFT JOIN MST_CFETS_CUSTOMER_INFO mcp ON iqc.cp_party_id = mcp.party_id LEFT JOIN MST_CFETS_CUSTOMER_TRADER mcct ON iqc.CP_TRADER_ID = mcct.trader_id WHERE iqer.entrust_id = #{entrustId} union all select #{TRADE_FLOW_STATUS01} effectFlag,
from WFL_IBU_QUOTE_CREP iqc LEFT JOIN WFL_IBU_QUOTE_ETR_RE iqer ON iqer.QUOTE_ID = iqc.QUOTE_ID LEFT JOIN STL_SEC_ACCT_INFO ssai ON iqc.SEC_MANAGE_ACCT_ID = ssai.SEC_ACCT_ID LEFT JOIN PTL_PORTFOLIO pp ON iqer.portfolio_id = pp.portfolio_id LEFT JOIN MST_CFETS_CUSTOMER_INFO mcp ON iqc.cp_party_id = mcp.party_id LEFT JOIN MST_CFETS_CUSTOMER_TRADER mcct ON iqc.CP_TRADER_ID = mcct.trader_id WHERE iqer.entrust_id = #{entrustId}
